// src/doctor/setupCucumber.ts
import fs from "fs";
import path from "path";
function writeText(filePath, contents) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, contents.endsWith("\n") ? contents : `${contents}
`, "utf8");
}
function writeSmart(filePath, contents, force) {
  const existed = fs.existsSync(filePath);
  if (existed && !force) return "skipped";
  writeText(filePath, contents);
  return existed ? "updated" : "created";
}
function findCucumberConfig(cwd) {
  for (const name of ["cucumber.js", "cucumber.cjs", "cucumber.mjs", "cucumber.ts"]) {
    const p = path.join(cwd, name);
    if (fs.existsSync(p)) return p;
  }
  return null;
}
var DEFAULT_CUCUMBER_JS = `module.exports = {
  default: {
    paths: ['features/**/*.feature'],
    require: [
      'features/support/**/*.js',
      'features/step_definitions/**/*.js',
    ],
    format: ['progress', 'merv-client-cucumber'],
  },
};
`;
var DEFAULT_CUCUMBER_TS = `module.exports = {
  default: {
    paths: ['features/**/*.feature'],
    requireModule: ['ts-node/register'],
    require: [
      'features/support/**/*.ts',
      'features/step_definitions/**/*.ts',
    ],
    format: ['progress', 'merv-client-cucumber'],
  },
};
`;
function ensureFormatter(configPath) {
  let text = fs.readFileSync(configPath, "utf8");
  let changed = false;
  const details = [];
  if (text.includes("merv-client/cucumber-formatter") && !text.includes("merv-client-cucumber")) {
    text = text.split("merv-client/cucumber-formatter").join("merv-client-cucumber");
    changed = true;
    details.push("migrated legacy merv-client/cucumber-formatter \u2192 merv-client-cucumber");
  }
  if (text.includes("merv-client-cucumber")) {
    if (changed) {
      fs.writeFileSync(configPath, text, "utf8");
      return {
        step: "cucumber.js formatter",
        action: "updated",
        path: configPath,
        detail: details.join("; ")
      };
    }
    return {
      step: "cucumber.js formatter",
      action: "skipped",
      path: configPath,
      detail: "MERV formatter already registered"
    };
  }
  let next = text;
  if (/format\s*:\s*\[/.test(next)) {
    next = next.replace(/format\s*:\s*\[/, (m) => `${m}'merv-client-cucumber', `);
  } else if (/format\s*:\s*['"][^'"]+['"]/.test(next)) {
    next = next.replace(
      /format\s*:\s*(['"][^'"]+['"])/,
      `format: [$1, 'merv-client-cucumber']`
    );
  } else if (/default\s*:\s*\{/.test(next)) {
    next = next.replace(
      /default\s*:\s*\{/,
      `default: {
    format: ['progress', 'merv-client-cucumber'],`
    );
  }
  if (next === text) {
    return {
      step: "cucumber.js formatter",
      action: "failed",
      path: configPath,
      detail: "Could not auto-patch. Add format: ['progress', 'merv-client-cucumber'] manually"
    };
  }
  fs.writeFileSync(configPath, next, "utf8");
  return {
    step: "cucumber.js formatter",
    action: "updated",
    path: configPath,
    detail: "added merv-client-cucumber formatter (left other options intact)"
  };
}
function ensurePackageScripts(cwd) {
  const pkgPath = path.join(cwd, "package.json");
  if (!fs.existsSync(pkgPath)) {
    return { step: "package.json scripts", action: "skipped", detail: "no package.json" };
  }
  let pkg;
  try {
    pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
  } catch {
    return { step: "package.json scripts", action: "failed", path: pkgPath, detail: "invalid JSON" };
  }
  const scripts = { ...pkg.scripts || {} };
  const details = [];
  let changed = false;
  if (!scripts["show-report"]) {
    scripts["show-report"] = "merv show-report";
    changed = true;
    details.push("added show-report");
  }
  if (!scripts["test:cucumber"] && !scripts["cucumber"]) {
    scripts["test:cucumber"] = "cucumber-js";
    changed = true;
    details.push("added test:cucumber");
  }
  if (!changed) {
    return {
      step: "package.json scripts",
      action: "skipped",
      path: pkgPath,
      detail: "MERV scripts already present"
    };
  }
  pkg.scripts = scripts;
  fs.writeFileSync(pkgPath, `${JSON.stringify(pkg, null, 2)}
`, "utf8");
  return {
    step: "package.json scripts",
    action: "updated",
    path: pkgPath,
    detail: `${details.join(", ")} (left other fields unchanged)`
  };
}
function ensureFeatureDirs(cwd) {
  const steps = [];
  for (const rel of ["features", "features/support", "features/step_definitions"]) {
    const dir = path.join(cwd, rel);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
      steps.push({ step: "mkdir", action: "created", path: dir });
    }
  }
  if (!steps.length) {
    steps.push({
      step: "features/ layout",
      action: "skipped",
      path: path.join(cwd, "features"),
      detail: "directories already present"
    });
  }
  return steps;
}
function ensureDemoScaffold(cwd, language, force) {
  const steps = [];
  const ext = language === "typescript" ? "ts" : "js";
  const featuresDir = path.join(cwd, "features");
  let hasFeature = false;
  try {
    if (fs.existsSync(featuresDir)) {
      const walk = (dir) => {
        for (const name of fs.readdirSync(dir)) {
          const p = path.join(dir, name);
          const st = fs.statSync(p);
          if (st.isDirectory()) {
            if (walk(p)) return true;
          } else if (name.endsWith(".feature")) return true;
        }
        return false;
      };
      hasFeature = walk(featuresDir);
    }
  } catch {
  }
  if (hasFeature && !force) {
    steps.push({
      step: "features/",
      action: "skipped",
      path: featuresDir,
      detail: "feature files already present (not overwriting demos)"
    });
    return steps;
  }
  steps.push(...ensureFeatureDirs(cwd));
  const featurePath = path.join(featuresDir, "demo.feature");
  if (!fs.existsSync(featurePath) || force) {
    const action = writeSmart(
      featurePath,
      [
        "Feature: MERV demo",
        "  Scenario: Placeholder",
        "    Given MERV is configured",
        "    Then the report formatter is ready",
        ""
      ].join("\n"),
      force
    );
    steps.push({ step: "features/demo.feature", action, path: featurePath });
  }
  const worldPath = path.join(featuresDir, "support", `world.${ext}`);
  const worldBody = language === "typescript" ? `import { setWorldConstructor, World } from '@cucumber/cucumber';

export class MervWorld extends World {}

setWorldConstructor(MervWorld);
` : `const { setWorldConstructor, World } = require('@cucumber/cucumber');

class MervWorld extends World {}

setWorldConstructor(MervWorld);
`;
  if (!fs.existsSync(worldPath)) {
    steps.push({
      step: `features/support/world.${ext}`,
      action: writeSmart(worldPath, worldBody, force),
      path: worldPath
    });
  } else if (force) {
    steps.push({
      step: `features/support/world.${ext}`,
      action: writeSmart(worldPath, worldBody, true),
      path: worldPath
    });
  } else {
    const cur = fs.readFileSync(worldPath, "utf8");
    if (!cur.includes("setWorldConstructor")) {
      writeText(worldPath, worldBody);
      steps.push({
        step: `features/support/world.${ext}`,
        action: "updated",
        path: worldPath,
        detail: "corrected missing setWorldConstructor"
      });
    } else {
      steps.push({
        step: `features/support/world.${ext}`,
        action: "skipped",
        path: worldPath,
        detail: "already present"
      });
    }
  }
  const stepsPath = path.join(featuresDir, "step_definitions", `demo.steps.${ext}`);
  const stepsBody = language === "typescript" ? `import { Given, Then } from '@cucumber/cucumber';

Given('MERV is configured', async function () {
  // add setup here
});

Then('the report formatter is ready', async function () {
  // assertions / MervReporter calls here
});
` : `const { Given, Then } = require('@cucumber/cucumber');

Given('MERV is configured', async function () {
  // add setup here
});

Then('the report formatter is ready', async function () {
  // assertions / MervReporter calls here
});
`;
  if (!fs.existsSync(stepsPath) || force) {
    steps.push({
      step: `features/step_definitions/demo.steps.${ext}`,
      action: writeSmart(stepsPath, stepsBody, force),
      path: stepsPath
    });
  } else {
    steps.push({
      step: `features/step_definitions/demo.steps.${ext}`,
      action: "skipped",
      path: stepsPath,
      detail: "already present"
    });
  }
  return steps;
}
function ensureRequireHints(configPath, language) {
  const text = fs.readFileSync(configPath, "utf8");
  if (/require\s*:/.test(text)) {
    return {
      step: "cucumber.js require",
      action: "skipped",
      path: configPath,
      detail: "require already configured (left unchanged)"
    };
  }
  if (!/default\s*:\s*\{/.test(text)) {
    return {
      step: "cucumber.js require",
      action: "skipped",
      path: configPath,
      detail: "no default profile to patch"
    };
  }
  const ext = language === "typescript" ? "ts" : "js";
  const block = language === "typescript" ? `requireModule: ['ts-node/register'],
    require: [
      'features/support/**/*.${ext}',
      'features/step_definitions/**/*.${ext}',
    ],` : `require: [
      'features/support/**/*.${ext}',
      'features/step_definitions/**/*.${ext}',
    ],`;
  const next = text.replace(/default\s*:\s*\{/, `default: {
    ${block}`);
  if (next === text) {
    return {
      step: "cucumber.js require",
      action: "failed",
      path: configPath,
      detail: "could not insert require globs"
    };
  }
  fs.writeFileSync(configPath, next, "utf8");
  return {
    step: "cucumber.js require",
    action: "updated",
    path: configPath,
    detail: "added default require globs (left other options intact)"
  };
}
function setup(cwd, opts) {
  const force = !!opts.force;
  const steps = [];
  const existing = findCucumberConfig(cwd);
  if (existing) {
    steps.push(ensureFormatter(existing));
    steps.push(ensureRequireHints(existing, opts.language));
  } else {
    const created = path.join(cwd, "cucumber.js");
    const body = opts.language === "typescript" ? DEFAULT_CUCUMBER_TS : DEFAULT_CUCUMBER_JS;
    writeText(created, body);
    steps.push({ step: "cucumber.js", action: "created", path: created });
  }
  steps.push(ensurePackageScripts(cwd));
  steps.push(...ensureDemoScaffold(cwd, opts.language, force));
  return steps;
}
export {
  setup
};
